183		// 改提另一结果：退出码 1，原结果与文件保持原样。
184		out, errText, code := runCLI(t, file, "fail", " s1 ", "e1")
185		if code != exitRejected || strings.Contains(out, "结果已提交") {
186			t.Fatalf("改提另一结果应拒绝，code=%d out=%q err=%q", code, out, errText)
187		}
188		assertRecordUnchanged(t, file, before, "改提另一结果：")
189		if out, _, _ := runCLI(t, file, "show", " s1 "); !strings.Contains(out, "结果：通过") {
190			t.Fatalf("拒绝后 \" s1 \" 的 e1 应保留通过，out=%q", out)
191		}
192	}
