1	package credit
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	// 本文件为“申请免修时按用户给出的完整学生编号、要求编号与免修编号确定
9	// 申请归属”这项行为提供回归保障。记录文件可以合法保存带前后空白（普通
10	// 空格、制表符、全角空格 U+3000）的编号，成绩提交与免修撤销已按完整
11	// 编号办理，申请免修也必须如此：
12	//   - “s1”与“ s1 ”是两名不同学生，同一学生名下“r1”与“ r1 ”是两项
13	//     不同要求，“w1”与“ w1 ”是两份不同申请；普通空格、制表符、全角
14	//     空格都是编号内容，绝不能为了匹配而删掉；
15	//   - 给带空白的编号提交申请只命中编号完全一致的学生与要求，提示、免修
16	//     历史与核对来源都保留申请实际使用的编号，另一名学生的学分、要求与
17	//     申请保持原样，不改写已有编号、不合并记录；
18	//   - 完整学生编号不存在时按业务规则直接报错，不在任何学生名下新增历史；
19	//     学生存在而完整要求编号不存在时，即使去掉空白能碰上另一项要求，也
20	//     绝不借用，而是按原规则在申请人名下保存原要求编号、免修编号、依据
21	//     原文与拒绝原因，不获得学分；
22	//   - 编号为空字符串时直接拒绝，不创建申请；
23	//   - 命中已有申请后沿用现有规则：内容一致返回原结果，内容冲突拒绝修改，
24	//     已拒绝/已撤销的申请不因重试重新生效；新编号申请一项已有有效免修的
25	//     要求，仍只保留一条被拒绝的新申请，不产生第二份有效免修；
26	//   - 依据含实际文字时其前后与中间空白原样保留，纯空白依据仍按业务拒绝。
27	
28	// waiverWhitespaceTwoStudents 构造两名学生 "s1" 与 " s1 "：各有一项编号
29	// 为 r1 的要求，分别指向 4 学分课程 c1 与 3 学分课程 c2，两人都没有通过
30	// 修读或有效免修。
31	func waiverWhitespaceTwoStudents() *fileData {
32		return &fileData{
33			Version: recordVersion,
34			Courses: []*Course{
35				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
36				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
37			},
38			Students: []*Student{{ID: "s1"}, {ID: " s1 "}},
39			Requirements: []*Requirement{
40				{ID: "r1", StudentID: "s1", CourseID: "c1"},
41				{ID: "r1", StudentID: " s1 ", CourseID: "c2"},
42			},
43		}
44	}
45	
46	// TestApplyWaiverWhitespaceStudentIDHitsExactOwner 给 " s1 " 提交含实际
47	// 文字依据的新申请：只能满足 " s1 " 本人的 r1、获得本人 3 学分课程的
48	// 学分；申请按完整编号登记在本人名下，"s1" 的学分、要求与免修历史保持
49	// 原样。
50	func TestApplyWaiverWhitespaceStudentIDHitsExactOwner(t *testing.T) {
51		s, _ := mustLoadWhitespace(t, waiverWhitespaceTwoStudents())
52	
53		basis := "  学科竞赛获奖证明  "
54		w, action, err := s.ApplyWaiver(" s1 ", "r1", "w1", basis)
55		if err != nil || action != ActionCreated {
56			t.Fatalf("给 \" s1 \" 的申请应正常新建，得到 %+v action=%v err=%v", w, action, err)
57		}
58		// 申请实际使用的完整编号与依据原文都必须保留，绝不修剪。
59		if w.StudentID != " s1 " || w.ID != "w1" || w.ReqID != "r1" || w.Basis != basis {
60			t.Fatalf("申请应保留完整编号与依据原文，得到 %+v", w)
61		}
62		if w.Status != WaiverApproved {
63			t.Fatalf("依据含实际文字且要求存在应判有效，得到 %+v", w)
64		}
65	
66		// " s1 " 本人：3 学分、来源为本人的 w1。
67		rep := s.CheckStudent(" s1 ")
68		if !rep.Found || rep.TotalCredits != 3 || len(rep.Unmet) != 0 {
69			t.Fatalf("\" s1 \" 应凭本人 r1 获得 3 学分，得到 %+v", rep)
70		}
71		st := rep.Requirements[0]
72		if st.Req.ID != "r1" || st.Course.ID != "c2" || st.Course.Credit != 3 ||
73			!st.Satisfied || st.Source != "waiver" || st.WaiverID != "w1" {
74			t.Fatalf("\" s1 \" 的学分来源应是本人 3 学分课程与本人 w1，得到 %+v", st)
75		}
76	
77		// "s1" 保持原样：0 学分、r1 未满足、名下没有任何申请。
78		rep = s.CheckStudent("s1")
79		if rep.TotalCredits != 0 || len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
80			t.Fatalf("\"s1\" 应仍为 0 学分且 r1 未满足，得到学分=%d 未满足=%v",
81				rep.TotalCredits, rep.Unmet)
82		}
83		if st := rep.Requirements[0]; st.Satisfied || st.Source != "" {
84			t.Fatalf("\"s1\" 的要求不应被他人的申请满足，得到 %+v", st)
85		}
86		if len(rep.RejectedWaivers) != 0 || len(rep.RevokedWaivers) != 0 {
87			t.Fatalf("\"s1\" 名下不应出现任何免修申请，得到 拒绝=%v 撤销=%v",
88				rep.RejectedWaivers, rep.RevokedWaivers)
89		}
90		if ws := s.Waivers("s1"); len(ws) != 0 {
91			t.Fatalf("\"s1\" 的免修历史应保持为空，得到 %+v", ws)
92		}
93		if ws := s.Waivers(" s1 "); len(ws) != 1 || ws[0] != w {
94			t.Fatalf("申请应只记入 \" s1 \" 名下，得到 %+v", ws)
95		}
96	}
97	
98	// TestApplyWaiverWhitespaceReqIDIndependent 同一学生名下 "r1" 与 " r1 "
99	// 是两项不同要求（指向不同学分课程）：新申请只替代完整编号对应的那一项，
100	// 另一项保持未满足，两项要求互不借用。
101	func TestApplyWaiverWhitespaceReqIDIndependent(t *testing.T) {
102		d := &fileData{
103			Version: recordVersion,
104			Courses: []*Course{
105				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
106				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
107			},
108			Students: []*Student{{ID: "s1"}},
109			Requirements: []*Requirement{
110				{ID: "r1", StudentID: "s1", CourseID: "c1"},
111				{ID: " r1 ", StudentID: "s1", CourseID: "c2"},
112			},
113		}
114		s, _ := mustLoadWhitespace(t, d)
115	
116		w, action, err := s.ApplyWaiver("s1", " r1 ", "w1", "外校同层次课程")
117		if err != nil || action != ActionCreated || w.Status != WaiverApproved {
118			t.Fatalf("申请只应命中完整编号为 \" r1 \" 的要求，得到 %+v action=%v err=%v",
119				w, action, err)
120		}
121		if w.ReqID != " r1 " {
122			t.Fatalf("申请应保留完整要求编号 \" r1 \"，得到 %+v", w)
123		}
124	
125		rep := s.CheckStudent("s1")
126		if rep.TotalCredits != 3 {
127			t.Fatalf("只应计 \" r1 \" 对应课程的 3 学分，得到 %d", rep.TotalCredits)
128		}
129		statuses := map[string]RequirementStatus{}
130		for _, st := range rep.Requirements {
131			statuses[st.Req.ID] = st
132		}
133		if st := statuses[" r1 "]; !st.Satisfied || st.Source != "waiver" ||
134			st.WaiverID != "w1" || st.Course.Credit != 3 {
135			t.Fatalf("\" r1 \" 应由 w1 满足、计 3 学分，得到 %+v", st)
136		}
137		if st := statuses["r1"]; st.Satisfied || st.Source != "" || st.Course.Credit != 4 {
138			t.Fatalf("\"r1\" 不应被同号异写的申请满足，得到 %+v", st)
139		}
140		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
141			t.Fatalf("未满足要求应仍为 [r1]，得到 %v", rep.Unmet)
142		}
143	
144		// 再给不带空白的 r1 提交另一份申请：各自独立生效，不判编号冲突。
145		w2, action, err := s.ApplyWaiver("s1", "r1", "w2", "学科竞赛获奖")
146		if err != nil || action != ActionCreated || w2.Status != WaiverApproved {
147			t.Fatalf("给 r1 的新申请应独立生效，得到 %+v action=%v err=%v", w2, action, err)
148		}
149		if rep = s.CheckStudent("s1"); rep.TotalCredits != 7 || len(rep.Unmet) != 0 {
150			t.Fatalf("两项要求各计一份学分应为 7，得到学分=%d 未满足=%v",
151				rep.TotalCredits, rep.Unmet)
152		}
153	}
154	
155	// TestApplyWaiverWhitespaceWaiverIDIndependent 同一学生名下 "w1" 与
156	// " w1 " 是两份不同申请：分别保留、各自幂等，不能因去空白而返回另一份
157	// 申请或按另一份申请的内容报冲突。
158	func TestApplyWaiverWhitespaceWaiverIDIndependent(t *testing.T) {
159		d := &fileData{
160			Version: recordVersion,
161			Courses: []*Course{
162				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
163				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
164			},
165			Students: []*Student{{ID: "s1"}},
166			Requirements: []*Requirement{
167				{ID: "r1", StudentID: "s1", CourseID: "c1"},
168				{ID: "r2", StudentID: "s1", CourseID: "c2"},
169			},
170			Waivers: []*Waiver{
171				{ID: "w1", StudentID: "s1", ReqID: "r1", Basis: "依据一", Status: WaiverApproved},
172				{ID: " w1 ", StudentID: "s1", ReqID: "r2", Basis: "依据二", Status: WaiverApproved},
173			},
174		}
175		s, _ := mustLoadWhitespace(t, d)
176	
177		// 用 " w1 " 的原内容重复提交：必须返回带空格的那一份，不能返回 "w1"。
178		got, action, err := s.ApplyWaiver("s1", "r2", " w1 ", "依据二")
179		if err != nil || action != ActionExisted {
180			t.Fatalf("\" w1 \" 原内容重复提交应幂等命中本人，得到 %+v action=%v err=%v",
181				got, action, err)
182		}
183		if got.ID != " w1 " || got.ReqID != "r2" || got.Basis != "依据二" {
184			t.Fatalf("幂等返回的应是 \" w1 \" 原申请，得到 %+v", got)
185		}
186	
187		// 用 " w1 " 提交不同内容：冲突应针对 " w1 " 的原内容，绝不能拿 "w1"
188		// 的内容当作既有申请报冲突。
189		_, _, err = s.ApplyWaiver("s1", "r2", " w1 ", "换成别的依据")
190		if err == nil {
191			t.Fatal("同编号换内容应被拒绝")
192		}
193		msg := err.Error()
194		if !strings.Contains(msg, " w1 ") || !strings.Contains(msg, "依据二") {
195			t.Fatalf("冲突拒绝应点名 \" w1 \" 及其原依据，得到：%v", err)
196		}
197		if strings.Contains(msg, "依据一") {
198			t.Fatalf("冲突说明不能引用另一份申请 \"w1\" 的依据，得到：%v", err)
199		}
200	
201		// 两份申请各自原样保留。
202		if w := s.Waiver("s1", "w1"); w == nil || w.ReqID != "r1" ||
203			w.Basis != "依据一" || w.Status != WaiverApproved {
204			t.Fatalf("\"w1\" 应保持原样，得到 %+v", w)
205		}
206		if w := s.Waiver("s1", " w1 "); w == nil || w.ReqID != "r2" ||
207			w.Basis != "依据二" || w.Status != WaiverApproved {
208			t.Fatalf("\" w1 \" 应保持原样，得到 %+v", w)
209		}
210		if ws := s.Waivers("s1"); len(ws) != 2 {
211			t.Fatalf("两份申请应分别保留，得到 %+v", ws)
212		}
213	}
214	
215	// TestApplyWaiverWhitespaceNewIDDoesNotBorrowExisting 名下只有 "w1" 时，
216	// 用 " w1 " 提交（哪怕内容不同）是新编号的新申请，不能返回 "w1" 或按
217	// "w1" 的内容报冲突：目标要求已有有效免修时，按原规则保留一条被拒绝的
218	// 新申请，不产生第二份有效免修。
219	func TestApplyWaiverWhitespaceNewIDDoesNotBorrowExisting(t *testing.T) {
220		s, _ := mustLoadWhitespace(t, waiverWhitespaceTwoStudents())
221	
222		first, action, err := s.ApplyWaiver(" s1 ", "r1", "w1", "依据一")
223		if err != nil || action != ActionCreated || first.Status != WaiverApproved {
224			t.Fatalf("首次申请应生效，得到 %+v action=%v err=%v", first, action, err)
225		}
226	
227		// 用带空白的新编号再次申请同一要求：新建一条被拒绝记录，而不是硬冲突。
228		second, action, err := s.ApplyWaiver(" s1 ", "r1", " w1 ", "另一份依据")
229		if err != nil || action != ActionCreated {
230			t.Fatalf("新编号申请应作为独立申请落为被拒绝记录，得到 %+v action=%v err=%v",
231				second, action, err)
232		}
233		if second.ID != " w1 " || second.Status != WaiverRejected ||
234			second.ReqID != "r1" || second.Basis != "另一份依据" {
235			t.Fatalf("应保留新申请的完整编号、要求与依据，得到 %+v", second)
236		}
237		if !strings.Contains(second.Reason, "w1") {
238			t.Fatalf("拒绝原因应点名已有有效免修 w1，得到 %+v", second)
239		}
240	
241		// 原有效免修仍是唯一学分来源，3 学分只计一次。
242		rep := s.CheckStudent(" s1 ")
243		if rep.TotalCredits != 3 || len(rep.Unmet) != 0 {
244			t.Fatalf("拒绝第二份申请后仍只计一次 3 学分，得到学分=%d 未满足=%v",
245				rep.TotalCredits, rep.Unmet)
246		}
247		if st := rep.Requirements[0]; st.Source != "waiver" || st.WaiverID != "w1" {
248			t.Fatalf("来源应仍是原有效免修 w1，得到 %+v", st)
249		}
250		if len(rep.RejectedWaivers) != 1 || rep.RejectedWaivers[0].Waiver != second {
251			t.Fatalf("核对应列出被拒绝的新申请，得到 %+v", rep.RejectedWaivers)
252		}
253	
254		// 原样重复提交被拒绝的新申请：返回原拒绝结果，不重新生效。
255		again, action, err := s.ApplyWaiver(" s1 ", "r1", " w1 ", "另一份依据")
256		if err != nil || action != ActionExisted || again != second ||
257			again.Status != WaiverRejected {
258			t.Fatalf("被拒绝申请重复提交应幂等返回原结果，得到 %+v action=%v err=%v",
259				again, action, err)
260		}
261		if ws := s.Waivers(" s1 "); len(ws) != 2 {
262			t.Fatalf("重复提交不应新增申请，得到 %+v", ws)
263		}
264	}
265	
266	// TestApplyWaiverWhitespaceStudentNotFoundHardReject 完整学生编号不存在
267	// 时直接按业务规则报错：不创建申请、不在任何学生（含去掉空白能碰上的
268	// 另一名学生）名下新增历史、不产生变更。
269	func TestApplyWaiverWhitespaceStudentNotFoundHardReject(t *testing.T) {
270		cases := []string{" s1", "s1 ", "\ts1\t", "　s1　", "  s1  "}
271		for _, student := range cases {
272			t.Run(student, func(t *testing.T) {
273				s, _ := mustLoadWhitespace(t, waiverWhitespaceTwoStudents())
274	
275				w, _, err := s.ApplyWaiver(student, "r1", "w1", "学科竞赛获奖")
276				if err == nil {
277					t.Fatalf("学生 %q 不存在应直接报错，却得到申请 %+v", student, w)
278				}
279				if !strings.Contains(err.Error(), "不存在") || !strings.Contains(err.Error(), "学生") {
280					t.Fatalf("错误应明确说明学生不存在，得到：%v", err)
281				}
282				for _, sid := range []string{"s1", " s1 "} {
283					if ws := s.Waivers(sid); len(ws) != 0 {
284						t.Fatalf("学生 %q 被拒后不应在 %s 名下新增历史，得到 %+v",
285							student, sid, ws)
286					}
287					if rep := s.CheckStudent(sid); len(rep.RejectedWaivers) != 0 {
288						t.Fatalf("学生 %q 被拒后 %s 的核对不应出现拒绝记录", student, sid)
289					}
290				}
291				if s.Dirty() {
292					t.Fatalf("学生不存在的拒绝不应产生变更（学生 %q）", student)
293				}
294			})
295		}
296	}
297	
298	// TestApplyWaiverWhitespaceReqNotFoundSavedUnderApplicant 学生存在而完整
299	// 要求编号不存在时，即使去掉空白能碰上该学生名下的另一项要求，也按原
300	// 规则拒绝该申请：在申请人名下保存原要求编号、免修编号、依据原文与
301	// 拒绝原因，不借用另一项要求，不获得学分。
302	func TestApplyWaiverWhitespaceReqNotFoundSavedUnderApplicant(t *testing.T) {
303		d := &fileData{
304			Version: recordVersion,
305			Courses: []*Course{
306				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
307				{ID: "c2", Name: "线性代数", Credit: 3, Open: true},
308			},
309			Students: []*Student{{ID: "s1"}, {ID: " s1 "}},
310			Requirements: []*Requirement{
311				{ID: "r1", StudentID: "s1", CourseID: "c1"},
312				{ID: "r1", StudentID: " s1 ", CourseID: "c2"},
313			},
314		}
315		cases := []struct {
316			student string
317			req     string
318		}{
319			{"s1", " r1 "},
320			{"s1", "\tr1\t"},
321			{"s1", "　r1　"},
322			{" s1 ", " r1 "},
323			{" s1 ", "r2"},
324		}
325		for _, tc := range cases {
326			t.Run(tc.student+"/"+tc.req, func(t *testing.T) {
327				s, _ := mustLoadWhitespace(t, d)
328	
329				w, action, err := s.ApplyWaiver(tc.student, tc.req, "w9", "实际依据文字")
330				if err != nil || action != ActionCreated {
331					t.Fatalf("目标要求不存在应软拒绝并保留申请，得到 %+v action=%v err=%v",
332						w, action, err)
333				}
334				if w.Status != WaiverRejected {
335					t.Fatalf("申请应标记为已拒绝，得到 %+v", w)
336				}
337				// 申请人名下保存的必须是原编号与原依据，绝不修剪。
338				if w.StudentID != tc.student || w.ReqID != tc.req ||
339					w.ID != "w9" || w.Basis != "实际依据文字" {
340					t.Fatalf("拒绝记录应保留完整原编号与依据，得到 %+v", w)
341				}
342				if w.Reason == "" || !strings.Contains(w.Reason, tc.req) {
343					t.Fatalf("拒绝原因应点名原要求编号 %q，得到 %+v", tc.req, w)
344				}
345	
346				// 申请人不获得学分；其名下真实存在的 r1 仍未满足。
347				rep := s.CheckStudent(tc.student)
348				if rep.TotalCredits != 0 {
349					t.Fatalf("被拒绝的申请不获得学分，得到 %d", rep.TotalCredits)
350				}
351				if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
352					t.Fatalf("真实要求 r1 应仍未满足，得到 %v", rep.Unmet)
353				}
354				if len(rep.RejectedWaivers) != 1 || rep.RejectedWaivers[0].Waiver != w {
355					t.Fatalf("申请人核对中应列出这条拒绝记录，得到 %+v", rep.RejectedWaivers)
356				}
357				// 另一名学生名下不得出现任何历史，其要求与学分保持原样。
358				other := "s1"
359				if tc.student == "s1" {
360					other = " s1 "
361				}
362				if ws := s.Waivers(other); len(ws) != 0 {
363					t.Fatalf("拒绝历史不应记到另一名学生 %s 名下，得到 %+v", other, ws)
364				}
365			})
366		}
367	}
368	
369	// TestApplyWaiverWhitespaceEmptyIDsRejected 学生、要求、免修编号为空字符串
370	// 时一律直接拒绝：不创建申请、不产生变更；纯空白字符串仍是合法的完整编号
371	// （文件中不存在该学生时按学生不存在处理），不能与空字符串混为一谈。
372	func TestApplyWaiverWhitespaceEmptyIDsRejected(t *testing.T) {
373		// 从记录文件加载，使 store 初始不带未落盘变更，从而能验证空编号拒绝
374		// 不把 store 标记为已变更。
375		s, _ := mustLoadWhitespace(t, &fileData{
376			Version:      recordVersion,
377			Courses:      []*Course{{ID: "c1", Name: "数学", Credit: 4, Open: true}},
378			Students:     []*Student{{ID: "s1"}},
379			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
380		})
381	
382		for _, tc := range [][4]string{
383			{"", "r1", "w1", "依据"},
384			{"s1", "", "w1", "依据"},
385			{"s1", "r1", "", "依据"},
386		} {
387			w, _, err := s.ApplyWaiver(tc[0], tc[1], tc[2], tc[3])
388			if err == nil {
389				t.Fatalf("空编号 %v 应直接报错，却得到 %+v", tc, w)
390			}
391		}
392		if ws := s.Waivers("s1"); len(ws) != 0 {
393			t.Fatalf("空编号拒绝不得创建任何申请，得到 %+v", ws)
394		}
395		if s.Dirty() {
396			t.Fatal("空编号拒绝不应产生变更")
397		}
398	
399		// 纯空白学生编号不等于空字符串：文件中没有这名学生，按学生不存在
400		// 硬拒绝，同样不创建任何申请。
401		if _, _, err := s.ApplyWaiver(" ", "r1", "w1", "依据"); err == nil ||
402			!strings.Contains(err.Error(), "不存在") {
403			t.Fatalf("纯空白学生编号应按完整编号查找并报学生不存在，得到 %v", err)
404		}
405		if ws := s.Waivers("s1"); len(ws) != 0 {
406			t.Fatalf("纯空白编号被拒后不得在 s1 名下新增历史，得到 %+v", ws)
407		}
408	}
409	
410	// TestApplyWaiverWhitespaceBasisRulesUnchanged 依据的文字处理保持兼容：
411	// 纯空白依据仍按业务规则拒绝并保留“免修依据为空”的原因；含实际文字时
412	// 前后与中间空白随原文保留，再次提交必须逐字符一致才算内容相同。
413	func TestApplyWaiverWhitespaceBasisRulesUnchanged(t *testing.T) {
414		// 带空白编号的学生只能来自记录文件（登记入口仍会修剪编号）。
415		s, _ := mustLoadWhitespace(t, &fileData{
416			Version:      recordVersion,
417			Courses:      []*Course{{ID: "c2", Name: "线性代数", Credit: 3, Open: true}},
418			Students:     []*Student{{ID: " s1 "}},
419			Requirements: []*Requirement{{ID: "r1", StudentID: " s1 ", CourseID: "c2"}},
420		})
421	
422		// 纯空白依据（空格、制表符、全角空格混用）：软拒绝，原因不变。
423		w, action, err := s.ApplyWaiver(" s1 ", "r1", "wb", " \t 　 \n ")
424		if err != nil || action != ActionCreated || w.Status != WaiverRejected ||
425			w.Reason != "免修依据为空" {
426			t.Fatalf("纯空白依据应按原规则软拒绝，得到 %+v action=%v err=%v", w, action, err)
427		}
428		if rep := s.CheckStudent(" s1 "); rep.TotalCredits != 0 ||
429			len(rep.RejectedWaivers) != 1 {
430			t.Fatalf("纯空白依据申请不获得学分但应保留历史，得到 %+v", rep)
431		}
432	
433		// 含实际文字：依据原文（含前后空白）逐字符保留并判有效。
434		basis := "\t 学科竞赛获奖　 \n "
435		w, action, err = s.ApplyWaiver(" s1 ", "r1", "w1", basis)
436		if err != nil || action != ActionCreated || w.Status != WaiverApproved {
437			t.Fatalf("含实际文字的依据应判有效，得到 %+v action=%v err=%v", w, action, err)
438		}
439		if w.Basis != basis {
440			t.Fatalf("依据原文应逐字符保留，\nwant=%q\n got=%q", basis, w.Basis)
441		}
442	
443		// 去掉前后空白再提交：依据内容不同，按冲突拒绝，原依据保持不变。
444		if _, _, err := s.ApplyWaiver(" s1 ", "r1", "w1", "学科竞赛获奖"); err == nil {
445			t.Fatal("修剪后的依据与原文不同，应按内容冲突拒绝")
446		}
447		if got := s.Waiver(" s1 ", "w1"); got.Basis != basis || got.Status != WaiverApproved {
448			t.Fatalf("冲突拒绝后原依据与有效状态应保持不变，得到 %+v", got)
449		}
450	
451		// 原文再次提交：幂等返回原申请。
452		if got, a, err := s.ApplyWaiver(" s1 ", "r1", "w1", basis); err != nil ||
453			a != ActionExisted || got != w {
454			t.Fatalf("原文重复提交应幂等返回原申请，得到 %+v action=%v err=%v", got, a, err)
455		}
456	}
