1	package main
2	
3	import (
4		"os"
5		"strings"
6		"testing"
7	)
8	
9	// 本文件围绕“用 course 以原编号重新登记已有课程”的行为做命令行回归：
10	// 每次调用都重新打开记录文件，因此下列资料与核对检查同时覆盖落盘后再加载的结果。
11	//   - 课程未被任何课程要求引用：可用新名称与新的正整数学分原地更新，
12	//     开放/停开状态不因重新登记改变，课程列表仍只有这一份记录；
13	//   - 一旦被任意学生的课程要求引用（建立要求即生效，无需选课或通过）：
14	//     学分锁定，连同新名称一起的整次更新必须整单拒绝（退出码 1），
15	//     名称、学分、状态与记录文件都保持原样；
16	//   - 被引用后提交与原学分相同的新名称：允许只改名，编号与学分不变，
17	//     已有修读、免修、核对结论、学分来源与总学分都不受影响，停开仍停开；
18	//   - 未被引用时零或负数学分同样拒绝，且不能顺带改掉名称或状态。
19	
20	// mustReadRecord 读取记录文件当前内容，供拒绝前后逐字节比对。
21	func mustReadRecord(t *testing.T, file string) string {
22		t.Helper()
23		b, err := os.ReadFile(file)
24		if err != nil {
25			t.Fatalf("读取记录文件失败：%v", err)
26		}
27		return string(b)
28	}
29	
30	// assertRecordUnchanged 断言一次被拒绝的请求没有改写记录文件。
31	func assertRecordUnchanged(t *testing.T, file, before, label string) {
32		t.Helper()
33		if got := mustReadRecord(t, file); got != before {
34			t.Fatalf("%s不应改写记录文件\nbefore=%s\nafter=%s", label, before, got)
35		}
36	}
37	
38	// assertSingleCourseLine 断言课程列表中该编号只有一份记录，且整行与预期一致。
39	func assertSingleCourseLine(t *testing.T, file, wantLine string, courseID string) {
40		t.Helper()
41		out, _, code := runCLI(t, file, "list-courses")
42		if code != 0 {
43			t.Fatalf("列出课程失败 code=%d out=%q", code, out)
44		}
45		if strings.Count(out, "课程 "+courseID+"《") != 1 {
46			t.Fatalf("课程 %s 应只保留一份记录，实际列表：%q", courseID, out)
47		}
48		if !strings.Contains(out, wantLine) {
49			t.Fatalf("课程列表应包含 %q，实际：%q", wantLine, out)
50		}
51	}
52	
53	// TestCLICourseReregisterBeforeReferenceUpdatesInPlace 未被任何要求引用的开放
54	// 课程用原编号提交新名称与新的正整数学分：原地更新、列表只剩一份、状态继续
55	// 开放；此后建立的要求与修读核对都使用更新后的名称与学分。
56	func TestCLICourseReregisterBeforeReferenceUpdatesInPlace(t *testing.T) {
57		file := tempRecordFile(t)
58		for _, st := range [][]string{
59			{"student", "s1"},
60			{"course", "c1", "高等数学", "4"},
61		} {
62			if _, errText, code := runCLI(t, file, st...); code != 0 {
63				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
64			}
65		}
66	
67		// 新名称 + 新正整数学分：更新成功（退出码 0），不能被当成业务拒绝。
68		out, errText, code := runCLI(t, file, "course", "c1", "高等数学（上）", "5")
69		if code != 0 || !strings.Contains(out, "已更新") {
70			t.Fatalf("未被引用的课程应允许更新，code=%d out=%q err=%q", code, out, errText)
71		}
72	
73		// 列表只剩这一份记录，显示新名称、新学分，且仍为开放。
74		assertSingleCourseLine(t, file, "课程 c1《高等数学（上）》5 学分，状态：开放", "c1")
75		if out, _, _ := runCLI(t, file, "list-courses"); strings.Contains(out, "高等数学》") {
76			t.Fatalf("更新后不应再显示旧名称，out=%q", out)
77		}
78	
79		// 之后建立要求、选课并通过：核对必须使用更新后的名称与 5 学分。
80		for _, st := range [][]string{
81			{"req", "s1", "r1", "c1"},
82			{"enroll", "s1", "r1", "2024春", "e1"},
83			{"pass", "s1", "e1"},
84		} {
85			if _, errText, code := runCLI(t, file, st...); code != 0 {
86				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
87			}
88		}
89		out, _, code = runCLI(t, file, "check", "s1")
90		if code != 0 || !strings.Contains(out, "总学分：5") ||
91			!strings.Contains(out, "要求 r1（课程 c1《高等数学（上）》，5 学分）：已满足") ||
92			!strings.Contains(out, "来源为通过修读 e1") {
93			t.Fatalf("更新后的名称与 5 学分应进入核对，code=%d out=%q", code, out)
94		}
95		out, _, _ = runCLI(t, file, "show", "s1")
96		if !strings.Contains(out, "要求 r1 -> 课程 c1《高等数学（上）》5 学分") {
97			t.Fatalf("要求查询应显示更新后的课程资料，out=%q", out)
98		}
99	}
100	
101	// TestCLICourseReregisterClosedCourseKeepsClosed 已停开的课程在未被引用时
102	// 允许用原编号更新名称与学分，但更新后必须仍为停开，不能借重新登记恢复开放；
103	// 原有开放的课程更新后继续开放（见上一用例）。
104	func TestCLICourseReregisterClosedCourseKeepsClosed(t *testing.T) {
105		file := tempRecordFile(t)
106		for _, st := range [][]string{
107			{"course", "c1", "高等数学", "4"},
108			{"course-close", "c1"},
109		} {
110			if _, errText, code := runCLI(t, file, st...); code != 0 {
111				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
112			}
113		}
114	
115		out, _, code := runCLI(t, file, "course", "c1", "高等数学（下）", "6")
116		if code != 0 || !strings.Contains(out, "已更新") {
117			t.Fatalf("停开但未被引用的课程也应允许更新，code=%d out=%q", code, out)
118		}
119		assertSingleCourseLine(t, file, "课程 c1《高等数学（下）》6 学分，状态：停开", "c1")
120	
121		// 更新后仍停开：可以建立要求，但不能新增修读。
122		if _, errText, code := runCLI(t, file, "student", "s1"); code != 0 {
123			t.Fatalf("登记学生失败 code=%d err=%q", code, errText)
124		}
125		if _, errText, code := runCLI(t, file, "req", "s1", "r1", "c1"); code != 0 {
126			t.Fatalf("停开课程应仍可建立要求，code=%d err=%q", code, errText)
127		}
128		if _, errText, code := runCLI(t, file, "enroll", "s1", "r1", "2024春", "e1"); code != 1 {
129			t.Fatalf("更新后仍停开的课程不能新增修读，code=%d err=%q", code, errText)
130		}
131	}
132	
133	// TestCLICourseReregisterReferencedCreditLocksWholeUpdate 课程一被课程要求
134	// 引用（只有要求、没有任何选课或通过结果）学分即锁定：同时提交新名称与不同
135	// 学分必须整单拒绝（退出码 1），错误说明指出已被要求引用与原学分；
136	// 原名称、原学分、开放状态与记录文件全部保留，不能只改掉名称。
137	// 课程停开不解除该限制；整单拒绝后，按原学分只改名称仍应成功。
138	func TestCLICourseReregisterReferencedCreditLocksWholeUpdate(t *testing.T) {
139		file := tempRecordFile(t)
140		for _, st := range [][]string{
141			{"student", "s1"},
142			{"course", "c1", "高等数学", "4"},
143			{"req", "s1", "r1", "c1"},
144		} {
145			if _, errText, code := runCLI(t, file, st...); code != 0 {
146				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
147			}
148		}
149	
150		// 只有要求、没有选课或通过结果：锁定已经生效。
151		before := mustReadRecord(t, file)
152		out, errText, code := runCLI(t, file, "course", "c1", "高等数学（下）", "5")
153		if code != 1 {
154			t.Fatalf("已被要求引用时改学分应整单拒绝并退出码 1，code=%d out=%q err=%q",
155				code, out, errText)
156		}
157		if !strings.Contains(errText, "已被课程要求引用") ||
158			!strings.Contains(errText, "原学分 4") {
159			t.Fatalf("拒绝说明应指出已被要求引用及原学分 4，err=%q", errText)
160		}
161		assertRecordUnchanged(t, file, before, "被引用课程的整单更新")
162	
163		// 原名称、原学分、开放状态全部保留，只有一份记录。
164		assertSingleCourseLine(t, file, "课程 c1《高等数学》4 学分，状态：开放", "c1")
165		out, _, _ = runCLI(t, file, "check", "s1")
166		if !strings.Contains(out, "要求 r1（课程 c1《高等数学》，4 学分）：未满足") ||
167			!strings.Contains(out, "总学分：0") {
168			t.Fatalf("拒绝后要求核对仍应显示原名称与原学分，out=%q", out)
169		}
170	
171		// 整单被拒后按原学分只改名称：应成功，证明拒绝没有破坏课程资料。
172		if out, _, code := runCLI(t, file, "course", "c1", "高等数学（下）", "4"); code != 0 {
173			t.Fatalf("相同学分只改名称应成功，code=%d out=%q", code, out)
174		}
175		assertSingleCourseLine(t, file, "课程 c1《高等数学（下）》4 学分，状态：开放", "c1")
176	
177		// 停开不解除学分锁定。
178		if _, errText, code := runCLI(t, file, "course-close", "c1"); code != 0 {
179			t.Fatalf("停开课程失败 code=%d err=%q", code, errText)
180		}
181		closed := mustReadRecord(t, file)
182		if _, errText, code := runCLI(t, file, "course", "c1", "另一个名称", "5"); code != 1 {
183			t.Fatalf("停开不应解除学分锁定，code=%d err=%q", code, errText)
184		}
185		if !strings.Contains(errText, "已被课程要求引用") || !strings.Contains(errText, "原学分 4") {
186			t.Fatalf("停开后拒绝仍应说明被引用与原学分，err=%q", errText)
187		}
188		assertRecordUnchanged(t, file, closed, "停开课程的改学分请求")
189		assertSingleCourseLine(t, file, "课程 c1《高等数学（下）》4 学分，状态：停开", "c1")
190		out, _, _ = runCLI(t, file, "check", "s1")
191		if !strings.Contains(out, "要求 r1（课程 c1《高等数学（下）》，4 学分）：未满足") {
192			t.Fatalf("拒绝后名称与停开状态应保持，out=%q", out)
193		}
194	}
