245	// TestCLIWaiverWhitespaceReqNotFoundSavesRawIDsUnderApplicant 学生存在而
246	// 完整要求编号不存在（即使去掉空白能碰上本人的另一项要求）：退出码 1，
247	// 但申请按原规则保存在申请人名下——原要求编号、免修编号、依据原文与
248	// 拒绝原因都可在 show/check 中查到，不获得学分；重复提交返回原拒绝结果。
249	func TestCLIWaiverWhitespaceReqNotFoundSavesRawIDsUnderApplicant(t *testing.T) {
250		cases := []struct {
251			label   string
252			student string
253			req     string
254		}{
255			{"普通空格要求编号", "s1", " r1 "},
256			{"制表符要求编号", "s1", "\tr1\t"},
257			{"全角空格要求编号", "s1", "　r1　"},
258			{"带空白学生与要求", " s1 ", " r1 "},
259			{"完全不存在的要求编号", "s1", "rX"},
260		}
261		for _, tc := range cases {
262			t.Run(tc.label, func(t *testing.T) {
263				file, _ := writeDiskRecord(t, waiverWhitespaceCLITwoStudents())
264	
265				out, errText, code := runCLI(t, file, "waiver", tc.student, tc.req, " w9 ", "实际依据文字")
266				if code != exitRejected {
267					t.Fatalf("%s：目标要求不存在应业务拒绝，code=%d out=%q err=%q",
268						tc.label, code, out, errText)
269				}
270				// 提示保留完整免修编号，并说明已记入申请人历史。
271				if !strings.Contains(out, "免修申请  w9  已拒绝") ||
272					!strings.Contains(out, "已记入学生") {
273					t.Fatalf("%s：应说明申请已拒绝并记入历史，out=%q", tc.label, out)
274				}
275	
276				// 申请人核对：不学分别人的学分（s1=0、 s1 =0），被拒绝申请
277				// 按原要求编号列出。
278				check, _, code := runCLI(t, file, "check", tc.student)
279				if code != 0 || !strings.Contains(check, "总学分：0") {
