281				}
282				wantLine := "免修  w9 （要求 " + tc.req + "，依据 \"实际依据文字\"）"
283				if !strings.Contains(check, wantLine) {
284					t.Fatalf("%s：核对应按原要求编号列出拒绝记录 %q，check=%q",
285						tc.label, wantLine, check)
286				}
287	
288				// show 同样保留原要求编号、免修编号、依据与拒绝原因。
289				show, _, code := runCLI(t, file, "show", tc.student)
290				if code != 0 || !strings.Contains(show,
291					"免修  w9 ：要求 "+tc.req+"，依据 \"实际依据文字\"，状态：已拒绝") {
292					t.Fatalf("%s：show 应保留完整编号与依据原文，code=%d show=%q",
293						tc.label, code, show)
294				}
295	
296				// 原内容重复提交：返回原拒绝结果，退出码 0，不新增申请。
297				out2, _, code := runCLI(t, file, "waiver", tc.student, tc.req, " w9 ", "实际依据文字")
298				if code != 0 || !strings.Contains(out2, "免修  w9  已提交过且内容一致") {
299					t.Fatalf("%s：重复提交应幂等返回原拒绝申请，code=%d out2=%q",
300						tc.label, code, out2)
301				}
302				show, _, _ = runCLI(t, file, "show", tc.student)
303				if strings.Count(show, "免修  w9 ") != 1 {
