321	// TestCLIWaiverWhitespaceEmptyIDRejected 学生、要求、免修编号为空字符串时
322	// 退出码 1 且不创建申请，文件逐字节保持原样。
323	func TestCLIWaiverWhitespaceEmptyIDRejected(t *testing.T) {
324		file, raw := writeDiskRecord(t, waiverWhitespaceCLITwoStudents())
325		cases := [][]string{
326			{"", "r1", "w1", "依据"},
327			{"s1", "", "w1", "依据"},
328			{"s1", "r1", "", "依据"},
329		}
330		for _, args := range cases {
331			out, errText, code := runCLI(t, file, append([]string{"waiver"}, args...)...)
332			if code != exitRejected {
333				t.Fatalf("空编号 %v 应业务拒绝，code=%d out=%q err=%q", args, code, out, errText)
334			}
335			if !strings.Contains(errText, "不能为空") {
336				t.Fatalf("错误应说明编号为空，err=%q", errText)
337			}
338			assertFileByteIdentical(t, file, raw, "空编号拒绝：")
339		}
340		for _, sid := range []string{"s1", " s1 "} {
341			show, _, _ := runCLI(t, file, "show", sid)
342			if strings.Contains(show, "免修 w1") {
343				t.Fatalf("空编号拒绝不得创建任何申请，show(%s)=%q", sid, show)
344			}
345		}
346	}
347	
348	// TestCLIWaiverNewIDForAlreadyWaivedReqKeepsRejectedRecord 新免修编号申请
349	// 一项已有有效免修的要求：退出码 1，但保留一条独立的被拒绝新申请（不产生
350	// 第二份有效免修）；原有效免修仍是唯一学分来源，重复提交拒绝记录不重生。
351	func TestCLIWaiverNewIDForAlreadyWaivedReqKeepsRejectedRecord(t *testing.T) {
352		d := waiverWhitespaceCLITwoStudents()
353		d.Waivers = []diskWaiver{
354			{ID: "w1", Student: " s1 ", Req: "r1", Basis: "原获奖材料", Status: "approved"},
355		}
356		file, _ := writeDiskRecord(t, d)
357	
358		out, _, code := runCLI(t, file, "waiver", " s1 ", "r1", " w2 ", "新的外校修读证明")
359		if code != exitRejected || !strings.Contains(out, "已拒绝") {
360			t.Fatalf("已有有效免修时新编号申请应被拒绝并保留，code=%d out=%q", code, out)
361		}
362	
363		check, _, code := runCLI(t, file, "check", " s1 ")
364		if code != 0 || !strings.Contains(check, "总学分：3") {
365			t.Fatalf("仍应以原有效免修计一次 3 学分，code=%d check=%q", code, check)
366		}
367		for _, want := range []string{
368			"来源为有效免修 w1",
369			`免修  w2 （要求 r1，依据 "新的外校修读证明"）：该要求已有有效免修 w1`,
370		} {
371			if !strings.Contains(check, want) {
372				t.Fatalf("核对应保留原来源并列出被拒绝的新申请，check=%q（缺 %q）", check, want)
373			}
374		}
375	
376		// 被拒绝的新申请原样重复提交：仍退出码 0 幂等返回，不重新生效、不新增。
377		out, _, code = runCLI(t, file, "waiver", " s1 ", "r1", " w2 ", "新的外校修读证明")
378		if code != 0 || !strings.Contains(out, "状态：已拒绝") {
379			t.Fatalf("被拒绝申请重复提交应幂等返回原拒绝结果，code=%d out=%q", code, out)
380		}
381		show, _, _ := runCLI(t, file, "show", " s1 ")
382		if strings.Count(show, "免修  w2 ") != 1 {
383			t.Fatalf("被拒绝新申请应只保留一条，show=%q", show)
384		}
385		if strings.Count(show, "免修 w1：") != 1 {
386			t.Fatalf("原有效免修应保持唯一，show=%q", show)
387		}
388	}
