package credit

// Ready 表示基线可以运行。
func Ready() bool { return true }

package credit

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// 本文件为“读取已有记录时，同一学生的同一要求只能有一份有效免修”这项
// 业务规则提供回归保障。冲突无法经正常申请流程产生（第二份会在提交时被
// 拒绝），因此全部用例直接构造记录文件，聚焦 Load 读取历史这一路径：
//   - 文件本身完整、可解析，学生、课程、要求确实存在，两份免修依据非空，
//     只要同一学生同一要求下有两份编号不同的 approved 免修就整份拒绝；
//   - 一份 approved 与 rejected/revoked 历史共存是合法记录：核对只认那份
//     有效免修、学分只计一次，历史与原有原因逐条保留，失效申请不重新生效；
//   - 唯一性按“学生 + 要求”界定：不同学生共享要求编号、免修编号互不影响。

// writeRecord 将 d 序列化到临时记录文件，返回路径与写入的原始字节，
// 供调用方在拒绝读取后逐字节比对。
func writeRecord(t *testing.T, d *fileData) (path string, raw []byte) {
	t.Helper()
	buf, err := json.MarshalIndent(d, "", "  ")
	if err != nil {
		t.Fatalf("序列化测试记录失败：%v", err)
	}
	buf = append(buf, '\n')
	path = filepath.Join(t.TempDir(), "records.json")
	if err := os.WriteFile(path, buf, 0o600); err != nil {
		t.Fatalf("写入测试记录失败：%v", err)
	}
	return path, buf
}

// waiverConflictBase 构造一份结构完整、引用齐全的基础记录：
// 学生 s1 的要求 r1 指向 4 学分课程 c1。可选附一条已通过修读 e1。
func waiverConflictBase(withPass bool) *fileData {
	d := &fileData{
		Version: recordVersion,

package credit

import (
	"fmt"
	"math"
	"sort"
	"strconv"
)

// RequirementStatus 是核对时单项要求的判定结果。
type RequirementStatus struct {
	Req       *Requirement
	Course    *Course
	Satisfied bool
	// Source 为 "waiver"（有效免修）或 "enrollment"（通过修读）或 ""（未满足）。
	Source string
	// WaiverID 是当前有效免修编号（有有效免修时以此说明学分来源）。
	WaiverID string
	// PassedEnrollmentID 是用于说明来源的通过修读编号：
	// 没有有效免修时取最先提交的通过记录。
	PassedEnrollmentID string
	// PassedEnrollmentIDs 是该要求全部通过修读编号（修读历史），按提交先后。
	PassedEnrollmentIDs []string
}

// RejectedWaiver 是免修历史中被拒绝的申请及原因。
type RejectedWaiver struct {
	Waiver *Waiver
	Reason string
}

// Report 是按学生核对学分的结果。
type Report struct {
	StudentID string
	Found     bool // 学生是否存在
	// TotalCredits 已满足要求获得的学分之和；同一课程的多项要求各计一次，
	// 同一要求无论通过多少次或同时有免修都只计一份。
	// 当 Overflow 为 true 时，真实总和超出学分整数类型可表示的最大值，
	// TotalCredits 不再是可信结果，调用方必须拒绝展示本次核对。
	TotalCredits int
	// Overflow 表示该学生实际获得的总学分超出学分整数类型可表示的最大值。
	// 这只与本学生已满足的要求有关：各门课程学分本身仍然合法，未满足要求、
	// 选课或未通过的学分都不参与累计，其他学生的记录也不影响本判定，
	// 因此绝不能把它当作记录文件损坏。
	Overflow     bool
	Requirements []RequirementStatus
	// Unmet 是未满足的要求编号（保持 Requirements 中的顺序）。
	Unmet []string
	// RejectedWaivers 是该学生被拒绝的免修申请及具体原因，按申请顺序。
	RejectedWaivers []RejectedWaiver
	// RevokedWaivers 是已撤销免修编号，按申请顺序。
	RevokedWaivers []string
}

// CheckStudent 按学生核对学分。查询没有记录的学生时 Found=false。
func (s *Store) CheckStudent(studentID string) Report {
	rep := Report{StudentID: studentID}
	if _, ok := s.studentByID[studentID]; !ok {
		return rep
	}

